import React, { useState, useEffect } from 'react';
import { useSelector, useDispatch } from 'react-redux';
import { Link } from 'react-router-dom';
import { fetchMoodEntries, fetchMoodStats, setCurrentPeriod, clearMoodErrors } from '../redux/slices/moodSlice';
import MoodEntryForm from '../components/MoodEntryForm';
import MoodEntryCard from '../components/MoodEntryCard';
import './MoodTracker.css';

const MoodTracker = () => {
  const dispatch = useDispatch();
  const { 
    entries, 
    stats, 
    loading, 
    error, 
    currentPeriod 
  } = useSelector((state) => state.mood);
  
  const [showEntryForm, setShowEntryForm] = useState(false);
  
  useEffect(() => {
    dispatch(fetchMoodEntries());
    dispatch(fetchMoodStats(currentPeriod));
    
    // Clear any errors when component unmounts
    return () => {
      dispatch(clearMoodErrors());
    };
  }, [dispatch, currentPeriod]);
  
  const handlePeriodChange = (period) => {
    dispatch(setCurrentPeriod(period));
  };
  
  const toggleEntryForm = () => {
    setShowEntryForm(!showEntryForm);
    if (error) {
      dispatch(clearMoodErrors());
    }
  };
  
  const renderStats = () => {
    if (!stats) return null;
    
    return (
      <div className="mood-stats">
        <div className="stat-box">
          <span className="stat-label">Avg. Mood</span>
          <span className="stat-value">{stats.average_mood?.toFixed(1) || '-'}</span>
        </div>
        <div className="stat-box">
          <span className="stat-label">Avg. Energy</span>
          <span className="stat-value">{stats.average_energy?.toFixed(1) || '-'}</span>
        </div>
        <div className="stat-box">
          <span className="stat-label">Avg. Stress</span>
          <span className="stat-value">{stats.average_stress?.toFixed(1) || '-'}</span>
        </div>
        <div className="stat-box">
          <span className="stat-label">Avg. Sleep</span>
          <span className="stat-value">{stats.average_sleep?.toFixed(1) || '-'}</span>
        </div>
      </div>
    );
  };
  
  if (loading && !entries.length) {
    return (
      <div className="container mood-tracker-page">
        <div className="page-header">
          <h1>Mood Tracker</h1>
          <button 
            className="primary-button" 
            onClick={toggleEntryForm}
            disabled={loading}
          >
            {showEntryForm ? 'Cancel' : 'Add Entry'}
          </button>
        </div>
        
        <div className="loading-state">
          <div className="loading-spinner"></div>
          <p>Loading your mood data...</p>
        </div>
      </div>
    );
  }
  
  return (
    <div className="container mood-tracker-page">
      <div className="page-header">
        <h1>Mood Tracker</h1>
        <button 
          className="primary-button" 
          onClick={toggleEntryForm}
          disabled={loading}
        >
          {showEntryForm ? 'Cancel' : 'Add Entry'}
        </button>
      </div>
      
      {error && <div className="error-banner">{error}</div>}
      
      {showEntryForm ? (
        <MoodEntryForm onClose={toggleEntryForm} />
      ) : (
        <>
          {entries.length === 0 ? (
            <div className="empty-state">
              <div className="empty-icon">📊</div>
              <h2>No mood entries yet</h2>
              <p>Start tracking your mood to gain insights about your emotional well-being over time.</p>
              <button className="primary-button" onClick={toggleEntryForm}>Add Your First Entry</button>
            </div>
          ) : (
            <div className="mood-content">
              <div className="mood-chart-container">
                <div className="chart-header">
                  <h2>Mood Trends</h2>
                  <div className="period-filter">
                    <button 
                      className={`period-btn ${currentPeriod === 'week' ? 'active' : ''}`}
                      onClick={() => handlePeriodChange('week')}
                    >
                      Week
                    </button>
                    <button 
                      className={`period-btn ${currentPeriod === 'month' ? 'active' : ''}`}
                      onClick={() => handlePeriodChange('month')}
                    >
                      Month
                    </button>
                    <button 
                      className={`period-btn ${currentPeriod === 'year' ? 'active' : ''}`}
                      onClick={() => handlePeriodChange('year')}
                    >
                      Year
                    </button>
                  </div>
                </div>
                
                {renderStats()}
                
                <div className="chart-placeholder">
                  Mood trend visualization coming soon
                </div>
              </div>
              
              <div className="mood-entries-list">
                <h2>Recent Entries</h2>
                {entries.slice(0, 5).map((entry) => (
                  <MoodEntryCard key={entry.id} entry={entry} />
                ))}
                
                {entries.length > 5 && (
                  <div className="view-all-entries">
                    <Link to="/mood-history" className="link-button">View All Entries</Link>
                  </div>
                )}
              </div>
            </div>
          )}
        </>
      )}
    </div>
  );
};

export default MoodTracker;
